#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    int numberOfZigzagArrays(int n, int m) {
        long long MOD = 1000000007;
        if (n == 1) return m % MOD;
        vector<long long> dp_up(m + 1, 0), dp_down(m + 1, 0);
        for (int v = 1; v <= m; ++v) {
            dp_up[v] = v - 1;
            dp_down[v] = m - v;
        }
        for (int step = 3; step <= n; ++step) {
            vector<long long> next_up(m + 1, 0), next_down(m + 1, 0);
            long long pref = 0;
            for (int v = 1; v <= m; ++v) {
                next_up[v] = pref;
                pref = (pref + dp_down[v]) % MOD;
            }
            long long suff = 0;
            for (int v = m; v >= 1; --v) {
                next_down[v] = suff;
                suff = (suff + dp_up[v]) % MOD;
            }
            dp_up = move(next_up);
            dp_down = move(next_down);
        }
        long long ans = 0;
        for (int v = 1; v <= m; ++v) {
            ans = (ans + dp_up[v] + dp_down[v]) % MOD;
        }
        return ans;
    }
};

